<section class="page-head"><div><h1><?= e(\App\Services\OrderReference::display($order)) ?></h1><p><?= staff_status($order['status']) ?> <span><?= e($order['created_at']) ?></span></p></div><a class="btn btn-secondary" href="<?= e(url('/admin/orders')) ?>">All orders</a></section>
<div class="staff-order-grid"><section class="panel admin-order-contact"><h2>Contact and delivery</h2><p><strong><?= e($order['recipient_name_snapshot']??'Not recorded') ?></strong></p><p><?= e($order['contact_email_snapshot']??'') ?><br><?= e($order['contact_no_snapshot']??'') ?></p><p class="staff-delivery-address"><?= e($order['delivery_address_snapshot']) ?></p><p class="muted"><?= $order['payment_method']==='cod'?'Cash on delivery':'Card via Maya' ?></p></section>
<section class="panel"><h2>Recorded updates</h2><?php if(!empty($order['out_for_delivery_at'])): ?><p>Out for delivery · <?= e($order['out_for_delivery_at']) ?></p><?php endif; ?><?php if(!$order['events']): ?><p class="analytics-empty">No earlier status events were recorded.</p><?php else: ?><ol class="staff-order-timeline"><?php foreach($order['events'] as $event): ?><li><div><?= e(ucfirst($event['to_status'])) ?><time><?= e($event['created_at']) ?></time></div></li><?php endforeach; ?></ol><?php endif; ?></section></div>
<section class="panel"><div class="panel-head"><h2>Order items</h2><span class="muted small"><?= count($order['items']) ?> <?= count($order['items'])===1?'product':'products' ?></span></div><div class="order-table-wrap"><table><thead><tr><th scope="col">Item</th><th scope="col" class="num">Quantity</th><th scope="col" class="num">Unit price</th></tr></thead><tbody>
<?php foreach($order['items'] as $item): ?><tr><td><?= e($item['product_name_snapshot']) ?></td><td class="num"><?= (int)$item['quantity'] ?></td><td class="num">₱<?= e(number_format((float)$item['unit_price_snapshot'],2)) ?></td></tr><?php endforeach; ?>
</tbody><tfoot><?php if($order['delivery']): ?><tr><th colspan="2">Shipping</th><td class="num">₱<?= e(number_format((float)$order['delivery']['shipping_fee'],2)) ?></td></tr><?php endif; ?><tr><th colspan="2">Order total</th><td class="num">₱<?= e(number_format((float)$order['total'],2)) ?></td></tr></tfoot></table></div></section>